import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Spell Variants & Glyphs","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/variants-and-glyphs.md","filePath":"en/guide/magic/variants-and-glyphs.md"}'),l={name:"en/guide/magic/variants-and-glyphs.md"};function s(n,a,o,d,p,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="spell-variants-glyphs" tabindex="-1">Spell Variants &amp; Glyphs <a class="header-anchor" href="#spell-variants-glyphs" aria-label="Permalink to &quot;Spell Variants &amp; Glyphs&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Learned glyphs modify compatible Core Patterns with trade-offs.</li><li>A bounded complexity budget prevents unlimited stacking.</li><li>Preparing a base spell does not automatically prepare every variant.</li></ul><p><span id="spell-variants-and-glyphs"></span><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Learn a modifier</td><td>Discover a compatible change to shape, delivery, targeting, effect or stability.</td></tr><tr><td>Choose a trade-off</td><td>Gain a tactical benefit by accepting cost, difficulty, exposure or reduced effect elsewhere.</td></tr><tr><td>Prepare a variant</td><td>Extra memory complexity or reconstruction effort may be needed; the rule remains open.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Magery offers defined spell effects rather than a freely assembled spell for every cast.</td><td>Keep recognizable patterns, with bounded learned variations rather than unrestricted construction.</td></tr><tr><td>Skills and resources affect spell use.</td><td>Variant choices may also change costs, difficulty, materials and preparation needs.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">Official UO: Magery and Meditation</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A Glyph of Compression might concentrate a Fireball into a smaller area. That is a tactical alternative with a trade-off, not a guaranteed upgrade or a confirmed spell option.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Inscription may preserve variants in books or scrolls. Applying an augmentation requires knowing the underlying spell. Modifier compatibility, limits, ownership, consumption and memory costs remain open.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory</a> · <a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Learning spells</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/magic/variants-and-glyphs.html">Spell Variants &amp; Glyphs</a> design specification.</p>',18)])])}const f=e(l,[["render",s]]);export{m as __pageData,f as default};
